#include <iostream>

template <typename T>
T twice(T value) { return value + value; }

int main() {
    std::cout << twice(3) << "\n";
    std::cout << twice(2.5) << "\n";
}

#include <iostream>
#include <string>

template <typename T>
struct Box { T value; };

int main() {
    Box<int> pencils{4};
    Box<std::string> label{"Blue"};
    std::cout << pencils.value << " " << label.value << "\n";
}

